// And groups predicates with the AND operator between them.
func And(predicates ...predicate.InventoryTransaction) predicate.InventoryTransaction {
	return predicate.InventoryTransaction(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.InventoryTransaction) predicate.InventoryTransaction {
	return predicate.InventoryTransaction(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.InventoryTransaction) predicate.InventoryTransaction {
	return predicate.InventoryTransaction(sql.NotPredicates(p))
}
